items=[]
def add(page,section,relation,target,typ,needle,condition='',owner=''):
 ps=page if isinstance(page,list) else [page]
 raw='\n'.join(pmap[n]['text'] for n in ps)
 # Source span matching tolerates PDF layout whitespace only. Persist exact extracted span.
 chars=[];positions=[]
 for i,ch in enumerate(raw):
  if not ch.isspace():chars.append(ch);positions.append(i)
 compact=''.join(chars);query=re.sub(r'\s+','',needle);start=compact.find(query)
 if start<0:raise ValueError((ps,section,needle))
 evidence=raw[positions[start]:positions[start+len(query)-1]+1]
 items.append(dict(section=section,relation=relation,target=target,type=typ,condition=condition,owner=owner,pdf_pages=ps,evidence=evidence,review='agent_source_review',provenance='manual_reference_not_llm_output'))
